import { readFileSync, writeFileSync } from "node:fs";

const src = readFileSync("src/services/paragraphs.ts", "utf8");
const POOL = eval(src.match(/FALLBACK_PARAGRAPHS[^=]*=\s*(\[[\s\S]*?\n\]);/)[1]);

const q = (s) => `'` + String(s).replace(/'/g, "''") + `'`;

const values = POOL.map(
  (p) => `  (${q(p.category)}, ${q(p.difficulty)}, ${q(p.body)}, ${p.estimatedSeconds}, ${q(p.seedTag)})`
);

const sql = `-- Solo playground paragraph library.
-- Generated by scripts/gen-paragraph-seed.mjs from FALLBACK_PARAGRAPHS.
-- Re-run with: node scripts/gen-paragraph-seed.mjs
-- Run AFTER supabase/schema.sql.

-- Step 1. Dedupe.
-- public.paragraphs has no unique constraint on body, and the seed in schema.sql
-- ends in a bare "on conflict do nothing" that cannot dedupe. If that insert was
-- ever applied twice, the same body exists two or more times and the unique index
-- in step 2 will fail. Collapse duplicates, keeping the oldest row per body.
--
-- matches.paragraph_id is "on delete restrict", so repoint matches at the
-- surviving row before deleting anything.
--
-- Both statements below must order identically ("created_at, id") so that the
-- row the UPDATE repoints to is exactly the row the DELETE keeps.

with ranked as (
  select id, body, row_number() over (partition by body order by created_at, id) as rn
  from public.paragraphs
),
keeper as (
  select id, body from ranked where rn = 1
),
dupe as (
  select id, body from ranked where rn > 1
)
update public.matches m
set paragraph_id = keeper.id
from dupe
join keeper on keeper.body = dupe.body
where m.paragraph_id = dupe.id;

with ranked as (
  select id, row_number() over (partition by body order by created_at, id) as rn
  from public.paragraphs
)
delete from public.paragraphs p
using ranked
where ranked.rn > 1
  and p.id = ranked.id;

-- Step 2. Unique index on body, which is what makes the insert in step 3 idempotent.
create unique index if not exists paragraphs_body_unique on public.paragraphs (body);

-- Step 3. Only insert bodies that are not already stored.
insert into public.paragraphs (category, difficulty, body, estimated_seconds, seed_tag)
${values.map((r) => `select * from (values ${r}) as v(category, difficulty, body, estimated_seconds, seed_tag)`).join("\nunion all\n")}
on conflict (body) do nothing;
`;

writeFileSync("supabase/seed-paragraphs.sql", sql);
console.log(`wrote supabase/seed-paragraphs.sql with ${POOL.length} paragraphs`);
